func=r'''    const IMPORT_STOP=new Set("a as o os de da das do dos e em um uma para por com sem que qual quais como ao aos na nas no nos se sua seu ser sobre".split(" "));
    function resetImportControls(){el.bulkText.value="";pendingImportFile=null;el.importFile.value="";el.importFileName.textContent="Nenhum arquivo escolhido"}
    function importFingerprint(v){return normalizeSearchText(v).replace(/[^a-z0-9\s]/g," ").replace(/\s+/g," ").trim()}
    function importSimilarity(a,b){a=importFingerprint(a);b=importFingerprint(b);if(!a||!b)return 0;if(a===b)return 1;const A=new Set(a.split(" ").filter(x=>x.length>2&&!IMPORT_STOP.has(x))),B=new Set(b.split(" ").filter(x=>x.length>2&&!IMPORT_STOP.has(x)));const n=[...A].filter(x=>B.has(x)).length;if(n<3)return 0;const dice=2*n/(A.size+B.size),contain=n/Math.min(A.size,B.size),len=Math.min(a.length,b.length)/Math.max(a.length,b.length);return Math.max(dice,contain*.92)*.85+len*.15}
    function findImportDuplicate(card,cards){const f=importFingerprint(card.q);let best={score:0,index:-1};for(let i=0;i<cards.length;i++){const g=importFingerprint(cards[i].q);if(f&&f===g)return{type:"exact",index:i};const score=importSimilarity(card.q,cards[i].q);if(score>best.score)best={score,index:i}}return best.index>=0&&best.score>=.79?{type:"possible",index:best.index}:null}
    function cloneImportCard(card){const c=typeof structuredClone==="function"?structuredClone(card):JSON.parse(JSON.stringify(card));delete c.subject;return normalizeCard(c)}
    function importCards(cards){const subject=data.subjects.find(x=>x.id===(el.importCollection?.value||data.selected));if(!subject){setMessage(el.importMessage,"Selecione uma coleção de destino antes de importar.","error");return null}const pending=[];let fresh=0;cards.filter(Boolean).map(cloneImportCard).forEach((card,i)=>{const d=findImportDuplicate(card,subject.cards);if(!d){subject.cards.push(card);fresh++}else pending.push({type:d.type,existingIndex:d.index,incoming:card,decision:d.type==="exact"?"skip":"",id:`${Date.now()}-${i}`})});data.selected=subject.id;ensureAllQuestionCodes(data);return{subject,total:cards.length,newCount:fresh,exactCount:pending.filter(x=>x.type==="exact").length,possibleCount:pending.filter(x=>x.type==="possible").length,pending}}
    function importOptions(card){return card.type==="select-list"?(card.listItems||[]).map(x=>`${x.label} = ${x.answer}`).join("\n"):(card.options||[]).map((x,i)=>`${optionLetter(i)}) ${x}`).join("\n")}
    function importAnswer(card){return card.type==="select-list"?(card.a||""):(correctAnswerTextForCard(card)||"")}
    function importField(label,value,changed){return `<div class="import-field ${changed?"changed":""}"><b>${escapeHtml(label)}</b><pre>${escapeHtml(value||"Não informado")}</pre></div>`}
    function importSide(card,title,other){return `<article class="import-side"><h4>${escapeHtml(title)}</h4>${importField("Pergunta",card.q,importFingerprint(card.q)!==importFingerprint(other.q))}${importField(card.type==="select-list"?"Itens e respostas":"Alternativas",importOptions(card),normalizeAnswerText(importOptions(card))!==normalizeAnswerText(importOptions(other)))}${importField("Resposta correta",importAnswer(card),normalizeAnswerText(importAnswer(card))!==normalizeAnswerText(importAnswer(other)))}${importField("Explicação",card.explanation||"Sem explicação",normalizeAnswerText(card.explanation||"")!==normalizeAnswerText(other.explanation||""))}</article>`}
    function importDecisionLabel(v){return v==="replace"?"Substituir existente":v==="keep"?"Manter as duas":v==="skip"?"Não importar":"Aguardando decisão"}
    function renderImportReview(){const st=importReviewState;if(!st)return;const subject=data.subjects.find(x=>x.id===st.subjectId);st.activeIndex=Math.max(0,Math.min(st.activeIndex||0,st.pending.length-1));const active=st.pending[st.activeIndex],existing=subject?.cards[active.existingIndex];el.importTotalCount.textContent=st.total;el.importNewCount.textContent=st.newCount;el.importExactCount.textContent=st.exactCount;el.importPossibleCount.textContent=st.possibleCount;el.importPendingTitle.textContent=`Pendentes (${st.pending.length})`;el.importReviewNotice.textContent=`${st.newCount} nova${st.newCount===1?" foi":"s foram"} importada${st.newCount===1?"":"s"} automaticamente. Revise ${st.pending.length} pendente${st.pending.length===1?"":"s"}.`;el.importPendingList.innerHTML=st.pending.map((x,i)=>`<button class="import-pending-item ${i===st.activeIndex?"active":""}" type="button" data-import-review-index="${i}"><span class="import-tag ${x.type}">${x.type==="exact"?"Repetida":"Possível"}</span><span class="import-question">${escapeHtml(x.incoming.q)}</span><span class="import-choice">${escapeHtml(importDecisionLabel(x.decision))}</span></button>`).join("");el.importComparison.innerHTML=existing?importSide(existing,"Já existe na coleção",active.incoming)+importSide(active.incoming,"Nova do arquivo",existing):'<div class="empty">A questão existente não foi encontrada.</div>';el.importDecisionActions.querySelectorAll("[data-import-decision]").forEach(b=>b.classList.toggle("active",b.dataset.importDecision===active.decision));const done=st.pending.filter(x=>x.decision).length;el.importReviewProgress.textContent=`${done} de ${st.pending.length} decisões concluídas`;el.finishImportReview.disabled=done!==st.pending.length}
    function preserveImportStudyData(oldCard,newCard){const c=cloneImportCard(newCard);["questionCode","status","reviews","masteryCount","lastMasteryTestId","testPriority","totalCorrect","totalWrong","ratingCounts","lastRating","lostMasteryCount","attemptHistory","lastReviewedAt","createdAt","topic","subtopic"].forEach(k=>{if(oldCard[k]!==undefined)c[k]=oldCard[k]});return normalizeCard(c)}
    function finalizeImportReview(){const st=importReviewState;if(!st||st.pending.some(x=>!x.decision))return;const subject=data.subjects.find(x=>x.id===st.subjectId);let kept=0,replaced=0,skipped=0;st.pending.forEach(x=>{const old=subject.cards[x.existingIndex];if(x.decision==="replace"&&old){subject.cards[x.existingIndex]=preserveImportStudyData(old,x.incoming);replaced++}else if(x.decision==="keep"){const c=cloneImportCard(x.incoming);c.questionCode="";subject.cards.push(c);kept++}else skipped++});ensureAllQuestionCodes(data);const added=st.newCount+kept;importReviewState=null;el.importReviewPanel.hidden=true;el.importEntryPanel.hidden=false;resetImportControls();setMessage(el.importMessage,`Importação concluída: ${added} adicionada${added===1?"":"s"}, ${replaced} substituída${replaced===1?"":"s"} e ${skipped} não importada${skipped===1?"":"s"}.`);render()}
    function cancelImportReview(){const n=importReviewState?.newCount||0;importReviewState=null;el.importReviewPanel.hidden=true;el.importEntryPanel.hidden=false;resetImportControls();setMessage(el.importMessage,`${n} questão${n===1?" nova foi mantida":" novas foram mantidas"}. As repetidas não foram importadas.`);render()}

    function imageMimeFromName'''
s,n=re.subn(r'    function importCards\(cards\) \{.*?\n\s*function imageMimeFromName',func,s,count=1,flags=re.S)
