listener=r'''    el.bulkImport.addEventListener("click",async()=>{if(importReviewState||el.bulkImport.disabled)return;const label=el.bulkImport.textContent;el.bulkImport.disabled=true;el.bulkImport.textContent="Analisando...";try{const imported=pendingImportFile?await parseImportFile(pendingImportFile):parseImportText(el.bulkText.value);if(!imported.length){setMessage(el.importMessage,pendingImportFile?"Não encontrei questões válidas nesse arquivo.":"Cole questões no formato pergunta, linha ---, resposta.","error");return}imported.forEach(normalizeCard);const result=importCards(imported);if(!result)return;if(result.pending.length){importReviewState={subjectId:result.subject.id,total:result.total,newCount:result.newCount,exactCount:result.exactCount,possibleCount:result.possibleCount,pending:result.pending,activeIndex:0};el.importEntryPanel.hidden=true;el.importReviewPanel.hidden=false;setMessage(el.importMessage,"");render();renderImportReview()}else{resetImportControls();setMessage(el.importMessage,`${result.total} questão${result.total===1?"":"ões"} importada${result.total===1?"":"s"}. Nenhuma repetida foi encontrada.`);render()}}catch(error){console.error("[Fixa] Falha na importação:",error);setMessage(el.importMessage,"Não consegui concluir a análise. Verifique o arquivo e tente novamente.","error")}finally{el.bulkImport.disabled=false;el.bulkImport.textContent=label}});

    function formatImportPreview'''
s,n=re.subn(r'    el\.bulkImport\.addEventListener\("click", async \(\) => \{.*?\n\s*function formatImportPreview',listener,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f'listener: {n}')
events='''    el.importPendingList.addEventListener("click",event=>{const b=event.target.closest("[data-import-review-index]");if(!b||!importReviewState)return;importReviewState.activeIndex=Number(b.dataset.importReviewIndex)||0;renderImportReview()});
    el.importDecisionActions.addEventListener("click",event=>{const b=event.target.closest("[data-import-decision]");if(!b||!importReviewState)return;importReviewState.pending[importReviewState.activeIndex].decision=b.dataset.importDecision;const next=importReviewState.pending.findIndex((x,i)=>i>importReviewState.activeIndex&&!x.decision);if(next>=0)importReviewState.activeIndex=next;renderImportReview()});
    el.skipAllImportDuplicates.addEventListener("click",()=>{if(importReviewState){importReviewState.pending.forEach(x=>x.decision="skip");renderImportReview()}});
    el.keepAllImportDuplicates.addEventListener("click",()=>{if(importReviewState){importReviewState.pending.forEach(x=>x.decision="keep");renderImportReview()}});
    el.finishImportReview.addEventListener("click",finalizeImportReview);el.cancelImportReview.addEventListener("click",cancelImportReview);

    el.openGuidelines.addEventListener("click", openGuidelinesModal);'''
one('    el.openGuidelines.addEventListener("click", openGuidelinesModal);',events,'events')
